const raw = $input.first().json.stdout;                                                                   
// Backslash'leri parse öncesi düzelt                                                                          
const cleaned = raw.replace(/\\/g, '/');                                                                     
const data = JSON.parse(cleaned);              

const windowsPrefix = $parameter.windows_prefix;
const linuxPrefix = $parameter.linux_prefix;

if (data.path) {
  data.linux_path = data.path.replace(windowsPrefix, linuxPrefix);
}

return { json: data };

